cd /workspace && cat > /tmp/t1.py <<'EOF'
import json,sys,subprocess
case=json.load(open('examples.json'))[1]['input']
p=subprocess.run(['python3','project/solver.py'],input=json.dumps(case).encode(),capture_output=True)
print(p.returncode, p.stderr.decode()[:2000])
out=json.loads(p.stdout.decode())
exp=json.load(open('examples.json'))[1]['output']
got=out['cases'][0]; want=exp['cases'][0]
for k in want:
    if got.get(k)!=want[k]:
        print('DIFF',k)
        if k=='trace':
            for a,b in zip(got[k],want[k]):
                if a!=b: print(' got',a); print(' want',b)
        else:
            print(' got',got.get(k)); print(' want',want[k])
EOF
python3 /tmp/t1.py
